SELECT SUM(CASE WHEN r."year" = 2010 THEN res."points" ELSE 0 END) - SUM(CASE WHEN r."year" = 2009 THEN res."points" ELSE 0 END) AS points_diff FROM main."results" res JOIN main."races" r ON res."raceId" = r."raceId" JOIN main."drivers" d ON res."driverId" = d."driverId" WHERE d."driverRef" = 'button' AND r."year" IN (2009, 2010);
